    tests = []
    for l in range(1, 7):
        for n in range(1, 2 ** (l - 1) + 1):
            if rng.random() < 0.35:
                tests.append(f'{l} {n}')
    tests += ['1 1', '2 1', '2 2', '3 3', '4 6']
    tests += ['50 1', '50 562949953421312', '50 562949953421311', '50 281474976710656', '50 281474976710657']
    for _ in range(30):
        l = rng.randint(7, 50)
        tests.append(f'{l} {rng.randint(1, 2 ** (l - 1))}')
    for _ in range(5):
        tests.append(f'50 {rng.randint(1, 2 ** 49)}')
    return tests

